INSERT INTO feature VALUES('input-method','editor','Unicode input method','vscode-extension','implemented','ordinary',NULL,'A backslash command offers its Unicode glyphs through the suggest widget, a fork continuing one step at a time, on for gandr and per language for others; the table is generated from Agda''s input method and the W3C and LaTeX names, each pinned by digest.','contrib/gandr-vscode','contrib/gandr-vscode/src/input/trie.test.ts',NULL,NULL);
